contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address to) public {
        require(to != address(0));

        c.createGameItem("item", "uri", false, true, 0, 0, 0); if (__ESBMC_reverted()) return;

        c.safeTransferFrom(address(this), to, 0, 0, ""); if (__ESBMC_reverted()) return;

        assert(c.balanceOf(to, 0) == 0);
    }
}

