// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(address to) internal {
        vm.assume(to != address(0));
        try c.createGameItem("item", "uri", false, true, 0, 0, 0) {} catch { return; }
        try c.safeTransferFrom(address(this), to, 0, 0, "") {} catch { return; }
        assertTrue(c.balanceOf(to, 0) == 0);
    }

    function testFuzz_run(address to) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to);
    }

    receive() external payable {}
}
